import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String data = "";
        if (scanner.hasNextLine()) {
            data = scanner.nextLine();
        }
        scanner.close();

        String res = findGreeting(data);
        System.out.println(res);
    }

    public static String findGreeting(String str) {
        String word = "hello";
        int i = 0;
        for (char l : str.toCharArray()) {
            if (l == word.charAt(i)) {
                i++;
                if (i == word.length()) {
                    break;
                }
            }
        }
        return i == word.length() ? "YES" : "NO";
    }
}

